  SELECT id INTO v_section FROM bag_sections WHERE bag_id = v_bag AND name = $q$Insert system$q$;
  SELECT id INTO v_item FROM bag_items WHERE bag_id = v_bag AND custom_name = $q$Carl's HotShot Golf Mat System$q$;
