  -- item 11: Player Preferred Series Studio Golf Mat, Single Hitting, 7' x 4' and 8' x 4'
  SELECT id INTO v_section FROM bag_sections WHERE bag_id = v_bag AND name = $q$Launch monitor friendly$q$;
  SELECT id INTO v_item FROM bag_items WHERE bag_id = v_bag AND custom_name = $q$Player Preferred Series Studio Golf Mat, Single Hitting, 7' x 4' and 8' x 4'$q$;
  IF v_item IS NULL THEN
    INSERT INTO bag_items (bag_id, section_id, custom_name, brand, custom_description, why_chosen, notes, price_paid, item_type, specs, photo_url, quantity, sort_index)
    VALUES (v_bag, v_section, $q$Player Preferred Series Studio Golf Mat, Single Hitting, 7' x 4' and 8' x 4'$q$, $q$Fiberbuilt$q$, $q$the better player with a permanent bay and a camera launch monitor who wants fat shots punished and clean strikes rewarded$q$, $q$Players who got bored of the Grass Series bristles move here. Friendly Golfer chose it over the Softy for his own bay because of the height and the 2 x 4 panel, and the GCQuad and EYE XO crowd follow the hitting zone.$q$, $q$Pros: most realistic turf interaction in Fiberbuilt's line and in several head-to-heads; Foresight GCQuad testing cited by Breaking Eighty as best replicating real turf; large hitting panel suits GCQuad, EYE XO and two-golfer households; heavy base does not move; thin rubber borders blend into a floor
Cons: firm; fat shots bounce and carry about 30 yards (Friendly Golfer); too firm for high handicappers and anyone with elbow or wrist history; $1,299 to $2,499; hard to move once built
Known issues: visible indent in the hitting area after under 5,000 shots for one owner; others saw none at 8 months; owners expect the hitting section to need replacing in 1 to 2 years of regular use; green marks on irons after several months; only about 12 x 18 in of the center is true strip on some units; the rest is hard underneath
Room fit: 1.75 in height lines up with 1 in foam tiles plus turf; the 2 x 4 ft panel on the 8 x 4 covers the full GCQuad and EYE XO hitting zones, which is why it is the overhead-camera builder's mat
